{
  "application": "ppt-generation",
  "case_id": "case-scale-seal-leaderboard",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "ML researchers, AI lab leadership, and engineering managers evaluating frontier model capabilities",
    "tone": "data-forward, analytical, comparative"
  },
  "brief": {
    "title": "Scale SEAL Leaderboards: How Frontier Models Stack Up Across 20+ AI Benchmarks",
    "one_liner": "A comparative analysis of top-performing AI models across Scale Labs' benchmark suite spanning agentic coding, reasoning, safety, and multimodal capabilities.",
    "goal": "Understand which frontier models lead across different capability domains, identify emerging competitive dynamics between labs, and recognize the benchmarks that remain unsaturated."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks",
      "objective": "Cover slide with deck title, subtitle referencing 100+ models evaluated across agentic, frontier, safety, and multimodal benchmarks. Include Scale Labs branding context."
    },
    {
      "id": "benchmark-landscape-overview",
      "title": "20+ Benchmarks Spanning Four Capability Domains Evaluate 100+ Models",
      "objective": "Overview slide showing the four benchmark categories (Agentic, Frontier, Safety, Multimodal) with example benchmarks in each. Use a categorized grid or icon layout to convey breadth."
    },
    {
      "id": "agentic-coding-leaders",
      "title": "GPT-5.4 Dominates Agentic Coding: Top Scores on SWE Atlas and SWE-Bench Pro",
      "objective": "Grouped bar chart or table comparing top 3 models on SWE Atlas Test Writing, SWE Atlas Codebase QnA, SWE-Bench Pro (Public), and SWE-Bench Pro (Private). Highlight GPT-5.4 variants and Claude Opus 4.6 as leading contenders."
    },
    {
      "id": "frontier-reasoning-rankings",
      "title": "GPT-5.4-Pro Leads Humanity's Last Exam at 44.3% — Scores Remain Below 50%",
      "objective": "Horizontal bar chart showing top models on Humanity's Last Exam, EnigmaEval, and MultiChallenge. Emphasize that even top scores are well below saturation, indicating these benchmarks still challenge frontier models."
    },
    {
      "id": "multimodal-audio-vision",
      "title": "Gemini Models Sweep Audio and Vision-Language Benchmarks",
      "objective": "Side-by-side comparison charts for AudioMultiChallenge (text and audio output) and VISTA. Show Gemini variants holding top positions across all three leaderboards. Reference the visual assets showing bar charts from these benchmarks."
    },
    {
      "id": "safety-alignment-results",
      "title": "Claude Models Score 95–96% on MASK Honesty Benchmark; Fortress Scores Stay Low",
      "objective": "Contrasting visualization: Claude's near-ceiling MASK scores vs. very low Fortress scores (8–13 range). Use this to illustrate that safety alignment varies dramatically by task type. Include PropensityBench data showing o3 at 10.5."
    },
    {
      "id": "lab-competitive-landscape",
      "title": "OpenAI, Google, and Anthropic Each Claim #1 Across Different Domains",
      "objective": "Summary matrix or heatmap showing which lab's model ranks #1 on each benchmark. OpenAI leads coding and reasoning, Google leads multimodal/audio, Anthropic leads safety and professional reasoning. Highlight Muse Spark as a notable new entrant."
    },
    {
      "id": "takeaways-implications",
      "title": "Key Takeaways: No Single Model Wins Everything — Specialization Is the New Frontier",
      "objective": "Bullet-point summary slide with 4–5 key findings: (1) GPT-5.4 leads agentic/reasoning but not multimodal, (2) Gemini dominates audio/vision, (3) Claude leads safety/honesty, (4) Key benchmarks like HLE (44%), EnigmaEval (24%), and SciPredict (25%) remain far from saturation, showing substantial room for improvement, (5) New entrant Muse Spark is a strong competitor, ranking top 3 on 6+ benchmarks spanning coding, tool use, and reasoning — including #1 on MultiChallenge at 75.5%."
    }
  ]
}

